<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';require __DIR__.'/commerce-fixture.php';require __DIR__.'/support/HttpTestServer.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Security\Principal;use Hostider\Services\{Engine,Worker,Runner,Policies};
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();$f=serviceFixture($db,1,true);$c=new \Hostider\Commerce\Services($db,$f['config']);$admin=commerceAdmin($c);$db->execute("INSERT INTO identity_customers(id,name,currency) VALUES (?,'Synthetic HTTP service account','USD')",[$f['customer']]);$client=commerceUser($c,'service-http-client');$outsider=commerceUser($c,'service-http-outsider');$db->execute('INSERT INTO identity_memberships(user_id,customer_id,is_owner) VALUES (?,?,TRUE)',[$client['user'],$f['customer']]);$role=$db->execute("SELECT id FROM identity_roles WHERE name='Müşteri Sahibi'")->fetchColumn();$db->transaction(fn()=>$c->identity->assign($client['user'],$role,$f['customer']));
$assignment=$db->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL LIMIT 1',[$admin['user']])->fetchColumn();foreach(['services.view','services.approve','services.reconcile','services.renew','services.wallet','services.cancel','services.suspend','services.unsuspend','services.terminate','services.package','identity.customers.view'] as $permission){$db->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope,service_scope) VALUES (?,?,?,?,?)',[Id::uuid(),$assignment,$permission,$f['customer'],'*']);}
$pool=(new \Hostider\Hosting\Pools($db,$f['config']))->configure($f['product'],100);$env=array_merge(getenv(),['APP_ENV'=>'test','APP_URL'=>$f['config']->url,'APP_KEY'=>$f['config']->key,'DB_DSN'=>$f['config']->dsn,'DB_USER'=>$f['config']->dbUser,'DB_PASSWORD'=>$f['config']->dbPassword,'PROVISIONING_ALLOWED'=>'false','PAYMENT_LIVE_ALLOWED'=>'false','EXTERNAL_MAIL_ALLOWED'=>'false']);$server=new HttpTestServer(dirname(__DIR__),$env,__DIR__.'/commerce-router.php');$jars=['admin'=>[],'client'=>[]];$tokens=['admin'=>'','client'=>''];
function serviceHttp(string $path,?array $data=null,?string $key=null,bool $csrf=true): array
{
    global $server,$jars,$tokens;$context=str_contains($path,'/admin/')?'admin':'client';$options=[];if($jars[$context]!==[]){$options[CURLOPT_COOKIE]=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($jars[$context]),$jars[$context]));}if($data!==null){$headers=['Content-Type: application/json','Idempotency-Key: '.($key??Id::uuid())];if($csrf){$headers[]='X-CSRF-Token: '.$tokens[$context];}$options += [CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode((object)$data,JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>$headers];}[$status,$raw,$headers]=$server->request($path,$options);foreach($headers as $header){if(preg_match('/^Set-Cookie: ([^=]+)=([^;]*)/i',$header,$m)){$jars[$context][$m[1]]=$m[2];}}$body=is_string($raw)?json_decode($raw,true):null;if(isset($body['data']['csrf'])){$tokens[$context]=$body['data']['csrf'];}return [$status,$body,$raw];
}
function serviceCommand(string $context,string $action,array $payload,?string $customer=null): array
{
    $data=['action'=>$action,'payload'=>(object)$payload];if($customer!==null){$data['customer']=$customer;}$review=serviceHttp('/api/v1/'.$context.'/services/prepare',$data);if($review[0]!==200){return $review;}$data['confirmation']=(object)['id'=>$review[1]['data']['id'],'accepted'=>true];return serviceHttp('/api/v1/'.$context.'/services/execute',$data);
}
function newHttpService(bool $active=true,string $scenario='SUCCESS'): string
{
    global $db,$c,$f,$admin;$now=new DateTimeImmutable('now',new DateTimeZone('UTC'));$actor=new Principal('service-http-fixture',[],customerId:$f['customer']);$order=$db->transaction(function()use($c,$f,$now,$actor): array{$quote=$c->quotes->issue($c->quotes->plan($f['customer'],new \Hostider\Finance\Currency('USD'),$f['cart'],[],$now));$order=$c->orders->submit($quote['id'],$f['customer'],['currency'=>'USD','name'=>'Synthetic HTTP service'],$actor,Id::uuid(),$now);$money=new \Hostider\Finance\Money($quote['total_minor'],new \Hostider\Finance\Currency('USD'));$payment=$c->finance->recordTestCollection($f['customer'],$money,Id::uuid(),$actor,Id::uuid());$c->orders->fund($order['id'],$f['customer'],$money,'COLLECTION',$payment,Id::uuid(),$actor,Id::uuid());return $order;});$engine=new Engine($db,$f['config']);$id=$engine->discover($order['id'],$actor,Id::uuid())[0];$c->identity->withStepUp($admin['reference'],'admin',function(array $u,array $s)use($db,$c,$f,$id): void{(new Policies($db,$f['config']))->set('SERVICE',$id,['price_protected'=>false,'price_notice_required'=>false,'allow_cancel'=>true,'termination_wait_seconds'=>5],0,$c->identity->principal($u,$s));});
    if($active){$c->identity->withStepUp($admin['reference'],'admin',function(array $u,array $s)use($c,$f,$id,$engine): void{$engine->approve($id,$f['customer'],$c->identity->authorize($u,$s,'services.approve',$f['customer'],$id,privileged:true),Id::uuid());});$operation=$engine->repository->find($id,lock:false)['current_operation_id'];(new Worker($db,$f['config']))->once($actor,$operation,$scenario);}return $id;
}
try{
    same(200,serviceHttp('/api/v1/client/identity/bootstrap')[0]);same(200,serviceHttp('/api/v1/client/identity/login',['email'=>$client['email'],'password'=>$client['password']])[0]);same(200,serviceHttp('/api/v1/client/identity/switch',['customer'=>$f['customer']])[0]);same(200,serviceHttp('/api/v1/client/identity/step-up',['password'=>$client['password']])[0]);same(200,serviceHttp('/api/v1/admin/identity/bootstrap')[0]);same(200,serviceHttp('/api/v1/admin/identity/login',['email'=>$admin['email'],'password'=>$admin['password']])[0]);same(200,serviceHttp('/api/v1/admin/identity/mfa',['code'=>$admin['recovery'][0]])[0]);same(200,serviceHttp('/api/v1/admin/identity/step-up',['password'=>$admin['password'],'code'=>$admin['recovery'][1]])[0]);
    test('F3-F HTTP client allowlist never returns provider resources credentials or old financial IDs',function(): void{$id=newHttpService();$response=serviceHttp('/api/v1/client/services/detail?id='.$id);same(200,$response[0]);same('ACTIVE',$response[1]['data']['status']);foreach(['resources','operations','attempts','inspections','inspection_jobs','order_id','customer_id','billing_request_id','server_id','external_id','credential_encrypted','snapshot_encrypted'] as $field){same(false,array_key_exists($field,$response[1]['data']));}same(true,is_string($response[1]['data']['price']['total_minor']));});
    test('F3-F pure HTTP renewal preparation writes no quote order ledger job outbox or service change',function()use($db): void{$id=newHttpService();$tables=['pricing_quotes','orders','finance_journals','svc_operations','outbox_events','svc_configs','svc_periods','svc_renewals'];$before=[];foreach($tables as $table){$before[$table]=$db->execute('SELECT COUNT(*) FROM '.$table)->fetchColumn();}$review=serviceHttp('/api/v1/client/services/prepare',['action'=>'renew','payload'=>(object)['service_id'=>$id]]);same(200,$review[0]);same('360',$review[1]['data']['plan']['total_minor']);foreach($tables as $table){same($before[$table],$db->execute('SELECT COUNT(*) FROM '.$table)->fetchColumn());}});
    test('F3-F confirmation is actor payload state bound and requires explicit accepted flag',function()use($db): void{$id=newHttpService();$data=['action'=>'wallet-opt-in','payload'=>(object)['service_id'=>$id,'enabled'=>true]];$review=serviceHttp('/api/v1/client/services/prepare',$data);same(200,$review[0]);$data['confirmation']=(object)['id'=>$review[1]['data']['id'],'accepted'=>false];same(403,serviceHttp('/api/v1/client/services/execute',$data)[0]);$data['confirmation']->accepted=true;$db->execute('UPDATE svc_services SET version=version+1 WHERE id=?',[$id]);same(409,serviceHttp('/api/v1/client/services/execute',$data)[0]);same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_preferences WHERE service_id=?',[$id])->fetchColumn());});
    test('F3-F HTTP one-use confirmation and cached replay still require current permission and step-up',function()use($db): void{$id=newHttpService();$data=['action'=>'wallet-opt-in','payload'=>(object)['service_id'=>$id,'enabled'=>true]];$review=serviceHttp('/api/v1/client/services/prepare',$data);same(200,$review[0]);$data['confirmation']=(object)['id'=>$review[1]['data']['id'],'accepted'=>true];$key=Id::uuid();same(200,serviceHttp('/api/v1/client/services/execute',$data,$key)[0]);same(200,serviceHttp('/api/v1/client/services/execute',$data,$key)[0]);same(409,serviceHttp('/api/v1/client/services/execute',$data)[0]);$role=$db->execute("SELECT id FROM identity_roles WHERE name='Müşteri Sahibi'")->fetchColumn();$db->execute("DELETE FROM identity_role_permissions WHERE role_id=? AND permission='services.wallet'",[$role]);try{same(403,serviceHttp('/api/v1/client/services/execute',$data,$key)[0]);}finally{$db->execute("INSERT INTO identity_role_permissions(role_id,permission) VALUES (?,'services.wallet')",[$role]);}same(1,(int)$db->execute("SELECT COUNT(*) FROM svc_events WHERE service_id=? AND kind='WALLET_OPT_IN_CHANGED'",[$id])->fetchColumn());});
    test('F3-F cached success cannot bypass expired client step-up',function()use($db,$client): void{$id=newHttpService();$data=['action'=>'wallet-opt-in','payload'=>(object)['service_id'=>$id,'enabled'=>true]];$review=serviceHttp('/api/v1/client/services/prepare',$data);same(200,$review[0]);$data['confirmation']=(object)['id'=>$review[1]['data']['id'],'accepted'=>true];$key=Id::uuid();same(200,serviceHttp('/api/v1/client/services/execute',$data,$key)[0]);$db->execute('UPDATE identity_sessions SET verified_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 10 MINUTE) WHERE user_id=? AND context=\'client\'',[$client['user']]);try{same(403,serviceHttp('/api/v1/client/services/execute',$data,$key)[0]);}finally{$db->execute('UPDATE identity_sessions SET verified_at=UTC_TIMESTAMP(6) WHERE user_id=? AND context=\'client\'',[$client['user']]);}});
    test('F3-F client and admin panels serve service controls and JavaScript',function(): void{foreach(['/client/services','/admin/services','/assets/services.js'] as $path){$response=serviceHttp($path);same(200,$response[0]);same(true,strlen($response[2])>100);}});
    test('F3-F HTTP CSRF and another customer cannot read or mutate service',function()use($outsider,$f,&$jars,&$tokens): void{$id=newHttpService();same(403,serviceHttp('/api/v1/client/services/prepare',['action'=>'cancel','payload'=>(object)['service_id'=>$id]],null,false)[0]);$saved=$jars['client'];$savedToken=$tokens['client'];$jars['client']=[];$tokens['client']='';try{serviceHttp('/api/v1/client/identity/bootstrap');same(200,serviceHttp('/api/v1/client/identity/login',['email'=>$outsider['email'],'password'=>$outsider['password']])[0]);same(200,serviceHttp('/api/v1/client/identity/step-up',['password'=>$outsider['password']])[0]);same(404,serviceHttp('/api/v1/client/services/detail?id='.$id)[0]);same(403,serviceHttp('/api/v1/client/services/list?customer='.$f['customer'])[0]);same(404,serviceHttp('/api/v1/client/services/prepare',['action'=>'cancel','payload'=>(object)['service_id'=>$id]])[0]);}finally{$jars['client']=$saved;$tokens['client']=$savedToken;}});
    test('F3-F scoped staff approval only queues then independent worker verifies activation',function()use($db,$f): void{$id=newHttpService(false);$response=serviceCommand('admin','approve',['service_id'=>$id],$f['customer']);same(200,$response[0]);same('QUEUED',(new \Hostider\Services\Repository($db,$f['config']))->find($id,lock:false)['status']);same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_resources WHERE service_id=?',[$id])->fetchColumn());$operation=$db->execute('SELECT current_operation_id FROM svc_services WHERE id=?',[$id])->fetchColumn();same(true,(new Runner($db,$f['config']))->once(new Principal('http-independent-worker',[]),$operation));same('ACTIVE',serviceHttp('/api/v1/client/services/detail?id='.$id)[1]['data']['status']);});
    test('F3-F HTTP UNKNOWN inspect is durable outside request TX then fresh staff resolves existing resource',function()use($db,$f): void{$id=newHttpService(true,'TIMEOUT_AFTER_CREATE');$requested=serviceCommand('admin','inspect',['service_id'=>$id],$f['customer']);same(200,$requested[0]);$job=$requested[1]['data']['inspection_job_id'];same('PENDING',$db->execute('SELECT status FROM svc_inspection_jobs WHERE id=?',[$job])->fetchColumn());same(true,(new Runner($db,$f['config']))->once(new Principal('inspection-worker',[]),$job));$row=$db->execute('SELECT status,inspection_id FROM svc_inspection_jobs WHERE id=?',[$job])->fetch();same('SUCCEEDED',$row['status']);same(200,serviceCommand('admin','resolve',['service_id'=>$id,'inspection_id'=>$row['inspection_id']],$f['customer'])[0]);same('ACTIVE',serviceHttp('/api/v1/client/services/detail?id='.$id)[1]['data']['status']);same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_hosting_accounts WHERE service_id=?',[$id])->fetchColumn());});
    test('F3-F inspect worker rejects stale staff freshness before provider read',function()use($db,$f,$admin): void{$id=newHttpService(true,'TIMEOUT_AFTER_CREATE');$requested=serviceCommand('admin','inspect',['service_id'=>$id],$f['customer']);same(200,$requested[0]);$job=$requested[1]['data']['inspection_job_id'];$reference=$db->execute('SELECT native_reference FROM identity_sessions WHERE user_id=? AND context=\'admin\' ORDER BY created_at DESC,id DESC LIMIT 1',[$admin['user']])->fetchColumn();$db->execute('UPDATE identity_sessions SET verified_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 10 MINUTE) WHERE native_reference=?',[$reference]);try{same(true,(new Runner($db,$f['config']))->once(new Principal('inspection-worker',[]),$job));same('FAILED',$db->execute('SELECT status FROM svc_inspection_jobs WHERE id=?',[$job])->fetchColumn());same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_inspections WHERE service_id=?',[$id])->fetchColumn());}finally{$db->execute('UPDATE identity_sessions SET verified_at=UTC_TIMESTAMP(6) WHERE native_reference=?',[$reference]);}});
    if(getenv('F3_BENCHMARK')==='1'){require dirname(__DIR__).'/tools/f3-benchmark-workload.php';}
    $exit=executeTests(true);
}finally{$server->stop();}
